import sys

class Node:
    def __init__(self, char, index, n):
        self.char = char
        self.index = index
        self.nextArray = [None] * 26
        self.hasCul = False
        self.isSame = False
        self.nextCount = 0
        self.nextList = []
        self.countArray = [0] * n

    def __str__(self):
        return self.char

    def addNext(self, index, node):
        if self.nextArray[index] is None:
            self.nextCount += 1
            self.nextArray[index] = node
            self.nextList.append(node)


def find(node):
    if node.hasCul:
        return

    node.countArray[0] += 1
    for nxt in node.nextList:
        find(nxt)
        for i in range(len(nxt.countArray)):
            if nxt.countArray[i] > 0:
                node.countArray[i + 1] += nxt.countArray[i]

    node.hasCul = True


def main():
    data = sys.stdin.read().split()
    idx = 0
    n = int(data[idx]); idx += 1
    k = int(data[idx]); idx += 1
    s = data[idx]; idx += 1

    sys.setrecursionlimit(max(10000, n * 10 + 100))

    letters = [False] * 26
    list_nodes = []
    for i in range(len(s)):
        char = s[i]
        node = Node(char, i, n)
        if letters[ord(char) - ord('a')]:
            node.isSame = True
        else:
            letters[ord(char) - ord('a')] = True
        list_nodes.append(node)

    for i in range(len(list_nodes)):
        ai = list_nodes[i]
        for j in range(i + 1, len(list_nodes)):
            aj = list_nodes[j]
            ai.addNext(ord(aj.char) - ord('a'), aj)

    for node in list_nodes:
        find(node)

    totalCountArray = [0] * n
    for i in range(n):
        for node in list_nodes:
            if not node.isSame:
                totalCountArray[i] += node.countArray[i]

    totalCost = 0
    selectCount = 0
    for i in range(n - 1, -1, -1):
        if selectCount + totalCountArray[i] < k:
            totalCost += (n - 1 - i) * totalCountArray[i]
            selectCount += totalCountArray[i]
        else:
            over = (selectCount + totalCountArray[i]) - k
            totalCost += (n - 1 - i) * (totalCountArray[i] - over)
            selectCount += (totalCountArray[i] - over)
            break

    if selectCount < k:
        if selectCount == k - 1:
            print(totalCost + n)
        else:
            print(-1)
    else:
        print(totalCost)


if __name__ == "__main__":
    main()
